import numpy as np
from scipy.optimize import minimize
import os

N = 26

def construct_packing() -> tuple:
    try:
        base_centers = np.loadtxt('storage/episteme/sota_base_centers.txt')
        base_radii = np.loadtxt('storage/episteme/sota_base_radii.txt')
    except Exception:
        return np.array([[0.5, 0.5]] * 26), np.array([0.05] * 26)

    def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
    def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]
    def ineq_boundary(z):
        c, r = z_to_cr(z)
        return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])
    def ineq_nonoverlap(z):
        c, r = z_to_cr(z)
        diff = c[:, None, :] - c[None, :, :]; dist = np.sqrt(np.sum(diff**2, axis=-1))
        iu = np.triu_indices(N, 1); return dist[iu] - (r[iu[0]] + r[iu[1]])
    def _ensure_validity(c, r):
        for _ in range(10):
            v=0
            for i in range(N):
                for j in range(i + 1, N):
                    dist = np.linalg.norm(c[i] - c[j]); rad_sum = r[i] + r[j]
                    if dist < rad_sum: v+=1; scale = (dist/rad_sum)*(1.0-1e-9); r[i]*=scale; r[j]*=scale
            if v==0: break
        return c, np.maximum(r, 0)

    # --- Stage 1: Find a Rigid, Eligible Packing ---
    def rigidity_objective(z):
        c, r = z_to_cr(z)
        primary_objective = -np.sum(r)
        penalty = 0.0
        penalty_weight = 10.0 # Very high penalty

        slacks = []
        for i in range(N):
            for j in range(i + 1, N):
                slacks.append(np.linalg.norm(c[i] - c[j]) - (r[i] + r[j]))
        slacks.sort()

        excess_pairs_1 = len([s for s in slacks if s < 1e-9])
        if excess_pairs_1 > 25: penalty += (excess_pairs_1 - 25) * penalty_weight

        excess_pairs_2 = len([s for s in slacks if s < 1e-8])
        if excess_pairs_2 > 15: penalty += (excess_pairs_2 - 15) * penalty_weight

        return primary_objective + penalty

    initial_z = cr_to_z(base_centers, base_radii)
    bounds = [(0,1)]*N*2 + [(1e-6, 0.5)]*N
    constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]

    res_stage1 = minimize(rigidity_objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 800, 'ftol': 1e-9})

    if not res_stage1.success:
        return _ensure_validity(base_centers, base_radii) # Fallback

    rigid_centers, rigid_radii = _ensure_validity(*z_to_cr(res_stage1.x))

    # --- Stage 2: Refine the Rigid Packing for Max Score ---
    def score_objective(z): return -np.sum(z[N*2:])

    best_score = -np.inf
    best_centers, best_radii = None, None
    jitter_amplitudes = [1e-4, 5e-4, 1e-3, 2e-3]
    restarts_per_amplitude = 4

    for amp in jitter_amplitudes:
        for i in range(restarts_per_amplitude):
            np.random.seed(int(amp * 1e6) + i + 2000)
            jitter = np.random.uniform(-amp, amp, size=rigid_centers.shape)
            perturbed_centers = np.clip(rigid_centers + jitter, 1e-6, 1 - 1e-6)
            stage2_z = cr_to_z(perturbed_centers, rigid_radii)

            res_stage2 = minimize(score_objective, stage2_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 500, 'ftol': 1e-9})

            if res_stage2.success:
                c_res, r_res = z_to_cr(res_stage2.x)
                c_final, r_final = _ensure_validity(c_res, r_res)
                final_score = np.sum(r_final)
                if final_score > best_score:
                    best_score = final_score
                    best_centers, best_radii = c_final, r_final

    if best_centers is None:
        return rigid_centers, rigid_radii

    return best_centers, best_radii
